$path=Resolve-Path 'wwwroot/app.js'
$s=[IO.File]::ReadAllText($path,[Text.Encoding]::UTF8)
# Remove park editing from the item form: the park belongs to the order reference.
$s=$s.Replace('<input class="new-order-input hidden" name="newOrderNumber" placeholder="\u041d\u043e\u0432\u044b\u0439 \u043d\u043e\u043c\u0435\u0440 \u0437\u0430\u043a\u0430\u0437\u0430"><input name="parkName" value="${esc(x.parkName||\'\')}" placeholder="\u041d\u0430\u0437\u0432\u0430\u043d\u0438\u0435 \u043f\u0430\u0440\u043a\u0430">','')
$s=$s.Replace("parkName:val('parkName'),",'')
$s=$s.Replace("const order=choice==='__new'?val('newOrderNumber'):choice", "const order=choice")
# The new order option is not offered in the item form.
$s=$s.Replace('<option value="__new">+ \u041d\u043e\u0432\u044b\u0439 \u043d\u043e\u043c\u0435\u0440 \u0437\u0430\u043a\u0430\u0437\u0430</option>','')
$s=$s.Replace("const n=document.querySelector('.new-order-input');n?.classList.toggle('hidden',e.target.value!=='__new');const o=(window.__orders||[]).find(z=>z.number===e.target.value);if(o)document.querySelector('[name=\"parkName\"]').value=o.parkName||''",'')
$settings=@'
function settings(){const rows=(window.__orders||[]).map(o=>`<div class="order-row"><b>${esc(o.number)}</b><input data-order-name="${esc(o.number)}" value="${esc(o.parkName||'')}"><button class="button" data-save-order="${esc(o.number)}">Сохранить</button></div>`).join('');const content=`<div class="modal-content"><div class="settings-grid"><div class="setting-card wide"><h3>Заказы и парки</h3><p>Заполните справочник. В изделии выбирается только номер заказа, а название парка подставляется из этой таблицы.</p><div class="order-manager">${rows}</div><div class="order-add"><input id="newOrderNumber" placeholder="Номер заказа"><input id="newOrderName" placeholder="Название парка"><button class="button primary" id="addOrderButton">Добавить заказ</button></div></div><div class="setting-card"><h3>Импорт Excel</h3><p>Импорт книги .xlsx в каталог.</p><input type="file" id="excelFile" accept=".xlsx"><button class="button primary" id="importButton">Импортировать</button></div><div class="setting-card"><h3>Экспорт базы</h3><p>Сохранить копию описаний изделий в JSON.</p><button class="button" id="exportButton">Экспорт JSON</button></div><div class="setting-card"><h3>Резервная копия</h3><p>Копируйте папку data целиком, включая uploads.</p></div></div></div>`;modal('Инструменты библиотеки','Справочники и резервная копия',content,`<footer class="modal-actions"><span></span><button class="button" id="settingsClose">Готово</button></footer>`);$('#settingsClose').onclick=closeModal;root.querySelectorAll('[data-save-order]').forEach(button=>button.onclick=async()=>{const number=button.dataset.saveOrder;const input=root.querySelector(`[data-order-name="${number}"]`);await api(`/api/orders/${encodeURIComponent(number)}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:input.value})});await refresh();settings();toast('Заказ обновлён')});$('#addOrderButton').onclick=async()=>{const number=$('#newOrderNumber').value.trim(),name=$('#newOrderName').value.trim();if(!number||!name)return toast('Введите номер и название парка');await api('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({number,name})});await refresh();settings();toast('Заказ добавлен')};$('#exportButton').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({categories,orders:window.__orders||[],items},null,2)],{type:'application/json'}));a.download='maf-library.json';a.click()};$('#importButton').onclick=async()=>{const f=$('#excelFile').files[0];if(!f)return toast('Выберите файл Excel');const fd=new FormData();fd.append('file',f);const result=await api('/api/import',{method:'POST',body:fd});await refresh();toast(`Добавлено изделий: ${result.added}`)}}
'@
$rx=[regex]::new('function settings\(\)\{.*?\}\r?\nfunction addCategory', [Text.RegularExpressions.RegexOptions]::Singleline)
if(-not $rx.IsMatch($s)){throw 'settings function not found'}
$s=$rx.Replace($s,$settings.Trim()+"`r`nfunction addCategory",1)
[IO.File]::WriteAllText($path,$s,[Text.UTF8Encoding]::new($false))
